/**
 * Blender's own AgX, as a 3D LUT (presentation mode's tone mapper: ./presentToneMapping.ts). The review stills of the lobby
 * (docs/screenshots/lobby-blender-*.jpg) are Blender 4.5's view transform "AgX" with the look "AgX - Base Contrast" (an identity grading in AgX
 * Log: the base AgX image formation of the Eary Chow / Troy Sobotka config, Linear CIE-XYZ E -> E-Gamut -> lg2 -> AgX_Base_sRGB.cube -> 2.4 power
 * -> sRGB). three's `AgXToneMapping` is an older approximation (the Filament inset matrix, a polynomial sigmoid, a 2.2 power): at the same
 * exposure it is lighter through the shadows and mid-tones (scene 0.18 -> display 0.50 against Blender's 0.46) and much less saturated (scene
 * (0.18, 0.009, 0.009) -> (0.51, 0.12, 0.11) against (0.44, 0.07, 0.03)). That is the "Blender looks better" contrast, so the LUT is Blender itself.
 *
 * How it was made (derived, not eyeballed; one headless Blender 4.5.14, `--factory-startup`): an N^3 grid of scene-linear Rec.709 colours,
 * each channel x = 0.18 * 2^(LO + s (HI - LO)) for s on N even steps of [0, 1] (red fastest, then green, then blue), written into a float image
 * (colour space "Linear Rec.709") and saved with `image.save_render()` as a 16-bit PNG under the scene's view settings (display sRGB, view "AgX",
 * look "AgX - Base Contrast", exposure 0, gamma 1, no curves, dither 0). The PNG was read back as data: the display code values (sRGB-encoded),
 * rounded to 8 bits here. The generator, for the record:
 *
 *   s = linspace(0, 1, N); b, g, r = meshgrid(s, s, s, indexing='ij'); x = 0.18 * 2 ** (LO + stack([r, g, b]) * (HI - LO))
 *   img = bpy.data.images.new('lut', 1024, H, float_buffer=True); img.colorspace_settings.name = 'Linear Rec.709'
 *   img.pixels.foreach_set(rgba); scene.view_settings.view_transform = 'AgX'; scene.view_settings.look = 'AgX - Base Contrast'
 *   scene.render.image_settings.color_depth = '16'; img.save_render(png, scene=scene)   # then load as Non-Color, round(v * 255)
 *
 * Accuracy (trilinear lookup of this table against 30 000 colours run through Blender directly): near-neutral colours (what a lobby is) mean
 * error 0.0007 of display range, 99th percentile 0.003 (under one 8-bit step); arbitrary colours mean 0.001, 99th percentile 0.007. The range,
 * LO = -10 to HI = +8.5 stops around 0.18, is AgX's own floor (-10: 0.18 x 2^-10 is black) up to where everything is white (+8.5 is display 1.0
 * on a grey; a channel brighter than +8.5 is read as +8.5: only the brightest saturated emitters, already nearly white, are touched).
 *
 * Data: the Blender AgX config is part of Blender's datafiles (colormanagement/config.ocio and luts/AgX_Base_sRGB.cube); this table is a numeric
 * sampling of that view transform, 33^3 x RGB bytes (SHA-256 of the raw bytes 977c9162ee8cb647dc405d5ed67705230f6b77fd01b8c150694aee68a4bfbf42).
 */

/** Grid points per axis. */
export const AGX_LUT_SIZE = 33
/** The shaper: log2 of the scene-linear value, mapped from [LOG2_MIN, LOG2_MAX] to [0, 1] (0.18 x 2^-10 .. 0.18 x 2^8.5). */
export const AGX_LUT_LOG2_MIN = Math.log2(0.18) - 10
export const AGX_LUT_LOG2_MAX = Math.log2(0.18) + 8.5

/** 33^3 RGB bytes, red fastest, then green, then blue: display (sRGB-encoded) code values x 255. */
const AGX_LUT_BASE64 =
  ''

let decoded: Uint8Array | null = null

/** The table as RGB bytes (decoded once, then shared). */
export function agxLutBytes(): Uint8Array {
  if (decoded) return decoded
  const bin = atob(AGX_LUT_BASE64)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  decoded = out
  return out
}

/** The table as RGBA bytes (alpha 255), the layout a Data3DTexture wants. */
export function agxLutRgba(): Uint8Array {
  const rgb = agxLutBytes()
  const n = AGX_LUT_SIZE ** 3
  const out = new Uint8Array(n * 4)
  for (let i = 0; i < n; i++) {
    out[i * 4] = rgb[i * 3]
    out[i * 4 + 1] = rgb[i * 3 + 1]
    out[i * 4 + 2] = rgb[i * 3 + 2]
    out[i * 4 + 3] = 255
  }
  return out
}

/** The shaper coordinate (0..1) of a scene-linear channel value, as the shader computes it. */
export function agxShaper(x: number): number {
  const l = Math.log2(Math.max(x, 1e-10))
  return Math.min(1, Math.max(0, (l - AGX_LUT_LOG2_MIN) / (AGX_LUT_LOG2_MAX - AGX_LUT_LOG2_MIN)))
}

/**
 * Blender's AgX of a scene-linear Rec.709 colour, as display (sRGB-encoded) values 0..1, written into `out`: the same trilinear lookup the
 * GPU makes. For tests and tools (the shader does this per pixel).
 */
export function agxBlenderDisplay(r: number, g: number, b: number, out: [number, number, number]): [number, number, number] {
  const lut = agxLutBytes()
  const n = AGX_LUT_SIZE
  const p = [agxShaper(r) * (n - 1), agxShaper(g) * (n - 1), agxShaper(b) * (n - 1)]
  const i = p.map((v) => Math.min(n - 2, Math.floor(v)))
  const f = p.map((v, k) => v - i[k])
  out[0] = out[1] = out[2] = 0
  for (let dr = 0; dr < 2; dr++)
    for (let dg = 0; dg < 2; dg++)
      for (let db = 0; db < 2; db++) {
        const w = (dr ? f[0] : 1 - f[0]) * (dg ? f[1] : 1 - f[1]) * (db ? f[2] : 1 - f[2])
        const at = ((i[2] + db) * n * n + (i[1] + dg) * n + (i[0] + dr)) * 3
        out[0] += (w * lut[at]) / 255
        out[1] += (w * lut[at + 1]) / 255
        out[2] += (w * lut[at + 2]) / 255
      }
  return out
}
